import json
with open('/app/resources/treasury_bulletin_1947_02.json', 'r') as f:
    data = json.load(f)

# Let's look at what the JSON structure contains
print("JSON keys:", list(data.keys()))

# Try to find any table with bond data
def search_dict(d, path=""):
    if isinstance(d, dict):
        for key, value in d.items():
            search_dict(value, f"{path}.{key}")
    elif isinstance(d, list) and len(d) > 0:
        # Check if any item contains what we're looking for
        if isinstance(d[0], dict):
            for item in d[:3]:
                if any('1938' in str(v) for v in item.values() if isinstance(v, str)):
                    print(f"Found at {path}: {item}")
                    return
        search_dict(d[0], f"{path}[0]")
    else:
        if '1938' in str(d):
            print(f"Found {d} at {path}")

